const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Jakarta Bay region (approximate coordinates)
  const jakartaBay = ee.Geometry.Polygon([
    [106.5, -6.0],
    [107.1, -6.0],
    [107.1, -6.3],
    [106.5, -6.3],
    [106.5, -6.0]
  ]);

  // Load Global Man-made Impervious Surface (GMIS) dataset for 2021
  // GMIS shows built-up/artificial surfaces
  const gmis = ee.ImageCollection('Oxford/MAP/GMIC_v1')
    .filterDate('2021-01-01', '2021-12-31')
    .filterBounds(jakartaBay);

  // Check data availability
  const collectionSize = gmis.size().getInfo();
  console.log(`2021 GMIS Images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get the built-up layer (impervious surface percentage)
  const builtUp = gmis.first().select('b1');

  // Threshold to identify artificial land (typically >30% impervious)
  const artificialLand = builtUp.gt(30);

  // Calculate area in square meters, then convert to hectares
  const areaStats = artificialLand.reduceRegion({
    reducer: ee.Reducer.sum().unweighted(),
    geometry: jakartaBay,
    scale: 1000,
    maxPixels: 1e9
  });

  const pixelArea = areaStats.get('b1').getInfo();

  // Check for valid pixels
  if (pixelArea === null || pixelArea === undefined) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  // Calculate area in hectares (1000m scale means 1 pixel = 1 hectare)
  const areaHectares = pixelArea;

  console.log(`Artificial land area: ${areaHectares.toFixed(2)} hectares`);
  console.log(`Valid pixels: ${pixelArea.toFixed(0)}`);

  // Validate result
  if (areaHectares === null || areaHectares === undefined || 
      areaHectares < 0 || areaHectares > 100000) { // Sanity check
    console.log("<answer>C3</answer>");
  } else if (areaHectares > 800) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
